-- CLEAN COMBINED ROBLOX LUA
-- Generated from the five supplied chunks.
-- Duplicate SXE variants were consolidated: Pasted text(9) is used as the
-- maintained core; Pasted text(7) and dontmatter.txt are not executed again.
-- The two distinct large systems are run in isolated environments to prevent
-- their local functions/variables from overwriting each other.

local function __runIsolated(__source, __name)
    local __loader = loadstring
    if type(__loader) ~= "function" then
        warn("[Combined] loadstring is unavailable; skipped " .. tostring(__name))
        return false
    end

    local __fn, __err = __loader(__source, __name)
    if not __fn then
        warn("[Combined] compile failed for " .. tostring(__name) .. ": " .. tostring(__err))
        return false
    end

    -- Give the module its own environment while retaining access to the
    -- executor/Roblox globals it needs. Explicit _G usage remains shared.
    local __env = setmetatable({
        script = script,
        _G = _G,
    }, {__index = getfenv and getfenv() or _G})

    if type(setfenv) == "function" then
        setfenv(__fn, __env)
    end

    local __ok, __result = pcall(__fn)
    if not __ok then
        warn("[Combined] runtime error in " .. tostring(__name) .. ": " .. tostring(__result))
        return false
    end
    return true
end

