        recoveryButton.BackgroundColor3=on and UI.C.BTN_ON or UI.C.BTN
    end
    recoveryButton=UI.smallButton({parent=body,x=8,y=tpY+166,w=206,h=26,textSize=11,
        onClick=function()
            local cfg=_G.SXE_Message40Config; if not cfg then return end
            cfg.HitRecovery=not (cfg.HitRecovery~=false)
            if not cfg.HitRecovery then _G.SXE_HitRecoveryCancel=true end
            refreshRecovery(); saveTp()
        end})
    refreshRecovery()

    RunService.Heartbeat:Connect(function()
        local cfg = _G.SXE_Message40Config
        if cfg and lastRecoveryState~=cfg.HitRecovery then
            lastRecoveryState=cfg.HitRecovery
            refreshRecovery()
        end
        if cfg and carpetOn ~= (cfg.WaveriderSpeedEnabled == true) then
            carpetOn = cfg.WaveriderSpeedEnabled == true
            if refreshUI then refreshUI() end
        end
    end)
    _G.SXE_KeybindActionsActive = true
    refreshUI = function()
        for _, b in ipairs(binds) do if b.refresh then pcall(b.refresh) end end
    end

end)

if not okCC then warn("[CARPET/CLONE] BLOC EN ERREUR: " .. tostring(errCC)) end
end)

end

