    local rows={}
    local function orderedTargets(api)
        local out,seen={},{}
        local entries={}
        if api and type(api.entries)=="function" then
            local ok,result=pcall(api.entries)
            if ok and type(result)=="table" then entries=result end
        end
        for _,entry in pairs(entries) do
            local alive=false
            if type(entry)=="table" and entry.uid and not seen[entry.uid] then
                if type(api.alive)=="function" then
                    local ok,result=pcall(api.alive,entry)
                    alive=ok and result==true
                else
                    alive=true
                end
            end
            if alive then
                seen[entry.uid]=true
                out[#out+1]=entry
            end
        end
        table.sort(out,function(a,b)
            local scoreA=_G.JAF_PrioScore and _G.JAF_PrioScore(a) or 999999
            local scoreB=_G.JAF_PrioScore and _G.JAF_PrioScore(b) or 999999
            if scoreA~=scoreB then return scoreA<scoreB end
            if a.plot~=b.plot then return tostring(a.plot)<tostring(b.plot) end
            if tonumber(a.slot) and tonumber(b.slot) and tonumber(a.slot)~=tonumber(b.slot) then return tonumber(a.slot)<tonumber(b.slot) end
            return tostring(a.uid)<tostring(b.uid)
        end)
        return out
    end
    local function updateList()
        local api=_G.SXE_StealTargetAPI
        if not api then return end
        local targets=orderedTargets(api)
        count.Text=tostring(#targets)
        empty.Visible=#targets==0
        local selected=api.selected()
        local seen={}
        for i,entry in ipairs(targets) do
            seen[entry.uid]=true
            local ui=rows[entry.uid]
            if not ui then
                local row=make("TextButton",scroll,{Size=UDim2.new(1,-4,0,35),BackgroundColor3=Color3.fromRGB(28,28,28),
                    BackgroundTransparency=0.27,BorderSizePixel=0,Text="",AutoButtonColor=false})
                corner(row,5)
                local title=make("TextLabel",row,{Size=UDim2.new(1,-12,0,19),Position=UDim2.fromOffset(7,2),BackgroundTransparency=1,
                    Font=Enum.Font.GothamBold,TextSize=11,TextColor3=Color3.new(1,1,1),TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd})
                local location=make("TextLabel",row,{Size=UDim2.new(1,-12,0,13),Position=UDim2.fromOffset(7,19),BackgroundTransparency=1,
                    Font=Enum.Font.GothamMedium,TextSize=9,TextColor3=Color3.fromRGB(170,170,170),TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd})
                ui={row=row,title=title,location=location}
                rows[entry.uid]=ui
                row.MouseButton1Click:Connect(function()
                    local currentApi=_G.SXE_StealTargetAPI
                    if currentApi and currentApi.select(ui.entry) then updateList() end
                end)
            end
            ui.entry=entry
            ui.row.LayoutOrder=i
            local picked=selected and selected.uid==entry.uid
            local mutation=tostring(entry.mutation or "None")
            ui.title.Text="#"..tostring(i).."  "..(mutation~="None" and mutation~="" and (mutation.."  ") or "")..tostring(entry.name)
            ui.title.TextColor3=picked and Color3.new(1,1,1) or mutationColors[mutation:lower()] or Color3.new(1,1,1)
            ui.location.Text="SLOT "..tostring(entry.slot).."  /  PLOT "..tostring(entry.plot)
            ui.location.TextColor3=picked and Color3.fromRGB(222,255,229) or Color3.fromRGB(170,170,170)
            ui.row.BackgroundColor3=picked and Color3.fromRGB(31,133,81) or Color3.fromRGB(28,28,28)
            ui.row.BackgroundTransparency=picked and 0.07 or 0.27
        end
        for uid,ui in pairs(rows) do
            if not seen[uid] then ui.row:Destroy(); rows[uid]=nil end
        end
    end
    while gui.Parent do
        updateList()
        task.wait(0.2)
    end
    dragChange:Disconnect()
    dragEnd:Disconnect()
end)


