          local function findTarget(data)
            local character = localPlayer.Character
            if not character then
              return
            end
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            local primaryPart = character.PrimaryPart or character:FindFirstChild("HumanoidRootPart")
            if not humanoid or not primaryPart or humanoid.Health <= 0 then
              return
            end
            local moveDirection = humanoid.MoveDirection
            if moveDirection.Magnitude > 0 and currentWalkSpeed > humanoid.WalkSpeed then
              primaryPart.CFrame = primaryPart.CFrame
                + moveDirection * (currentWalkSpeed - humanoid.WalkSpeed) * (data or 0.016666666666666666)
            end
          end
          local function toggleWalkspeed()
            if _G.SpeedBoostEnabled and not walkspeedEnabled then
              pcall(function()
