                  Duration = 2,
                })
              end)
              return
            end
            walkspeedEnabled = not walkspeedEnabled
            _G.walkspeedEnabled = walkspeedEnabled
            if connection then
              connection:Disconnect()
              connection = nil
            end
            pcall(function()
              if _G.movementPanelWalkspeedToggle then
                if walkspeedEnabled then
                  local movementPanelWalkspeedToggle = _G.movementPanelWalkspeedToggle
                  local movementPanelWalkspeedToggle2 = _G.movementPanelWalkspeedToggle
                  _G.movementPanelWalkspeedToggle.BackgroundColor3 = slateButtonColor
                  movementPanelWalkspeedToggle.BackgroundTransparency = 0
