      if not items[text2] then
        items[text2] = tick()
        if _G.autoKickEnabledTime < tick() then
          isEnabled = true
          local match = (label.Text:match("[Yy]ou%s+stole%s+(.+)") or "something")
            :gsub("<[^>]+>", "")
            :gsub("%s*%([Ee]rror%s+[Cc]ode:?%s*%d+%)%s*", "")
            :match("^%s*(.-)%s*$")
          if _G._xenPSLinkCode then
            pcall(function()
              if _G.triggerJoinPS then
                _G.triggerJoinPS()
              end
            end)
          else
            _G.KICK_IN_PROGRESS = true
