    local plots_2 = WorkspaceRoot:FindFirstChild("Plots")
    if not plots_2 then
      return nil
    end
    local huge = math.huge
    local state = nil
    for _, child in pairs(plots_2:GetChildren()) do
      local position = nil
      if child.PrimaryPart then
        position = child.PrimaryPart.Position
      elseif child:FindFirstChild("Base") then
        position = child.Base.Position
      elseif child:FindFirstChild("Floor") then
        position = child.Floor.Position
      else
        pcall(function()
          position = child:GetPivot().Position
        end)
      end
      if position then
        local magnitude = (humanoidRootPart.Position - position).Magnitude
        if magnitude < huge then
          state = child
          huge = magnitude
        end
      end
    end
    return state
  end
  local handleState = nil
  handleState = function(instance, data)
    for _, child in pairs(instance:GetChildren()) do
      if child:IsA("ProximityPrompt") then
        table.insert(data, child)
      end
      handleState(child, data)
    end
  end
  _G.unlockFloor = function(data)
    pcall(function()
      local instance = findTarget()
      if not instance then
        return
      end
