      if not unlock then
        return
      end
      local items = {}
      for _, child in pairs(unlock:GetChildren()) do
        local position = nil
        if child:IsA("Model") then
          pcall(function()
            position = child:GetPivot().Position
          end)
        elseif child:IsA("BasePart") then
          position = child.Position
        end
        if position then
          table.insert(items, {
            Object = child,
            Height = position.Y,
          })
        end
      end
      table.sort(items, function(data, data2)
        return data.Height < data2.Height
      end)
      if #items < data then
        return
      end
      local items2 = {}
      handleState(items[data].Object, items2)
      if #items2 == 0 then
        return
      end
      for _, item in pairs(items2) do
        fireproximityprompt(item)
      end
    end)
  end
