      return
    end
    local model = data:FindFirstAncestorOfClass("Model")
    if model and getValue(model) then
      return
    end
    pcall(function()
      for _, item in pairs(data:GetPlayingAnimationTracks()) do
        item:Stop(0)
      end
      local connection = data.AnimationPlayed:Connect(function(data)
        if _G.FPSDisableAnimations then
          data:Stop(0)
        end
      end)
      table.insert(items2, connection)
    end)
  end
