    end
    if localPlayer and localPlayer:GetAttribute("BackroomsCaveInside") then
      return
    end
    local model = instance:FindFirstAncestorOfClass("Model")
    model = model and getValue(model)
    if instance:IsA("Animator") then
      getValue2(instance)
    end
    if _G.AccessoryRemovalEnabled and (instance:IsA("Accessory") or instance:IsA("Clothing")) then
      if instance:FindFirstAncestorOfClass("Model") then
        pcall(function()
          instance:Destroy()
        end)
      end
    end
    if not model then
      if
        instance:IsA("ParticleEmitter")
        or instance:IsA("Trail")
        or instance:IsA("Smoke")
        or instance:IsA("Fire")
        or instance:IsA("Sparkles")
        or instance:IsA("Highlight")
      then
        pcall(function()
          instance.Enabled = false
        end)
      end
      if instance:IsA("Trail") then
        pcall(function()
          instance.Texture = ""
        end)
