        pcall(function()
          instance:Destroy()
        end)
      end
    elseif _G.AccessoryRemovalEnabled then
      if instance:IsA("MeshPart") then
        pcall(function()
          instance.TextureID = ""
        end)
      end
      if instance:IsA("BasePart") then
