      end
      local serverHopVisited = loadData()
      serverHopVisited[game.JobId] = true
      saveData(serverHopVisited)
      local serverHopCursor = _G._serverHopCursor
      local items = {}
      for i = 1, 8 do
        local success, callResult = pcall(decodeSettings, serverHopCursor)
        if not success or not callResult or not callResult.data then
          if serverHopCursor then
            _G._serverHopCursor = nil
            serverHopCursor = nil
            continue
          end
        else
          for _, item in ipairs(callResult.data) do
            local isActive = not serverHopVisited[item.id]
            if isActive then
              isActive = (item.playing or 0) < (item.maxPlayers or 999)
            end
            if isActive then
              items[#items + 1] = item.id
            end
          end
          serverHopCursor = callResult.nextPageCursor
          _G._serverHopCursor = serverHopCursor
          if not (0 < #items) then
            if serverHopCursor then
              continue
            end
          end
        end
        break
      end
      if #items == 0 then
        serverHopVisited = {
          [game.JobId] = true,
        }
        _G._serverHopVisited = serverHopVisited
        saveData(serverHopVisited)
        _G._serverHopCursor = nil
        local success, callResult = pcall(decodeSettings, nil)
        if success and callResult and callResult.data then
          for _, item in ipairs(callResult.data) do
            local isActive = not serverHopVisited[item.id]
            if isActive then
              isActive = (item.playing or 0) < (item.maxPlayers or 999)
            end
            if isActive then
              items[#items + 1] = item.id
            end
          end
          _G._serverHopCursor = callResult.nextPageCursor
        end
      end
      for i = #items, 2, -1 do
        local state = math.random(1, i)
        local entry = items[i]
        items[i] = items[state]
        items[state] = entry
      end
      for _, item in ipairs(items) do
        serverHopVisited[item] = true
        saveData(serverHopVisited)
        pcall(function()
          TeleportService:TeleportToPlaceInstance(game.PlaceId, item, PlayersService.LocalPlayer)
        end)
        task.wait(0.25)
      end
    end)
  end
