function _G.JAF_LoadHeavyNow() LPH_ATTRIBUTES(ERROR_HANDLING(false))
_G.JAF_HeavyReady = true end
if not _G.JAF_CacheFillWatch then
    _G.JAF_CacheFillWatch = true
