    JUI.new("TextLabel", row, "Size", UDim2.new(1,-14,1,0), "Position", UDim2.new(0,11,0,0), "BackgroundTransparency", 1, "Text", lbl, "Font", Enum.Font.GothamMedium, "TextSize", 10, "TextColor3", Theme.TextSecondary, "TextXAlignment", Enum.TextXAlignment.Left)
    return row
end
