    local kb = JUI.new("TextButton", row, "Size", UDim2.new(0,68,0,24), "Position", UDim2.new(1,-75,0.5,-12), "BackgroundColor3", Theme.SurfaceHighlight, "Text", get() or "NONE", "Font", Enum.Font.GothamMedium, "TextSize", 11, "TextColor3", Theme.Accent1, "AutoButtonColor", false)
    JUI.corner(kb, 5)
    kb.MouseButton1Click:Connect(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        kb.Text = "..."; kb.TextColor3 = Theme.TextPrimary
        local con; con = UserInputService.InputBegan:Connect(function(inp) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            if inp.UserInputType == Enum.UserInputType.Keyboard then
                set(inp.KeyCode.Name)
