            JUI.new("TextLabel", holder, "Size", UDim2.new(1, 0, 0, 24), "BackgroundTransparency", 1, "LayoutOrder", 0, "Text", "  Arrows set the fire order. PIN locks a slot in Random mode.", "Font", Enum.Font.GothamMedium, "TextSize", 11, "TextColor3", Color3.fromRGB(150, 150, 165), "TextXAlignment", Enum.TextXAlignment.Left, "TextWrapped", true)
            local bH = rowH - 8
