                JUI.new("TextLabel", r, "Size", UDim2.new(1, -116, 1, 0), "Position", UDim2.new(0, 10, 0, 0), "BackgroundTransparency", 1, "Text", i .. ".  " .. cmd:sub(1, 1):upper() .. cmd:sub(2) .. (enabled and "" or "   (off)"), "Font", Enum.Font.GothamBold, "TextSize", tSize, "TextColor3", enabled and Theme.TextPrimary or Color3.fromRGB(120, 120, 132), "TextXAlignment", Enum.TextXAlignment.Left)
                local function move(delta) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                    local j = i + delta
                    if j < 1 or j > #order then return end
                    order[i], order[j] = order[j], order[i]
                    if save then save() end
                    refresh()
                end
                local function mkBtn(txt, xOff, w, on) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                    local b = JUI.new("TextButton", r, "Size", UDim2.new(0, w, 0, bH), "Position", UDim2.new(1, xOff, 0.5, -bH / 2), "AutoButtonColor", false, "BorderSizePixel", 0, "Text", txt, "Font", Enum.Font.GothamBold, "TextSize", 11, "BackgroundColor3", on and Theme.Accent1 or Theme.SurfaceHighlight, "TextColor3", on and _G.JAF_OnAccent() or Theme.TextPrimary)
                    JUI.corner(b, 5)
                    return b
                end
                mkBtn("\u{25B2}", -92, 22, false).MouseButton1Click:Connect(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
move(-1) end)
                mkBtn("\u{25BC}", -66, 22, false).MouseButton1Click:Connect(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
move(1) end)
                mkBtn("PIN", -40, 34, pinned).MouseButton1Click:Connect(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                    if type(Config.AdminCmdPinned) ~= "table" then Config.AdminCmdPinned = {} end
                    Config.AdminCmdPinned[cmd] = (not pinned) or nil
                    if save then save() end
                    refresh()
                end) end
            holder.Size = UDim2.new(1, 0, 0, 24 + 6 + #order * (rowH + 6))
        end
        hdr.MouseButton1Click:Connect(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
