    isAtlasUser = _detector(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return Config.AntiApAtlasUsers end, function(username) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local folder = Workspace:FindFirstChild("AtlasESPFolder")
