    local function _slab(mn, mx, o, d) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local a, b = (mn - o) / d, (mx - o) / d
        if a > b then a, b = b, a end
        return a, b
    end
    local rayToCubeIntersect; rayToCubeIntersect = (function(rayOrigin, rayDirection, cubeCenter, cubeSize) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local halfSize = cubeSize / 2
        local minBounds = cubeCenter - Vector3.new(halfSize, halfSize, halfSize)
        local maxBounds = cubeCenter + Vector3.new(halfSize, halfSize, halfSize)
        local dx = rayDirection.X ~= 0 and rayDirection.X or 0.0001
        local dy = rayDirection.Y ~= 0 and rayDirection.Y or 0.0001
        local dz = rayDirection.Z ~= 0 and rayDirection.Z or 0.0001
        local tmin, tmax = _slab(minBounds.X, maxBounds.X, rayOrigin.X, dx)
        local tymin, tymax = _slab(minBounds.Y, maxBounds.Y, rayOrigin.Y, dy)
        if tmin > tymax or tymin > tmax then return false end
        if tymin > tmin then tmin = tymin end
        if tymax < tmax then tmax = tymax end
        local tzmin, tzmax = _slab(minBounds.Z, maxBounds.Z, rayOrigin.Z, dz)
        if tmin > tzmax or tzmin > tmax then return false end
        return true
    end)
    local _pickPlayerUnderRay; _pickPlayerUnderRay = (function(ray) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local hitboxSize, bestPlayer, bestDistance = 8, nil, math.huge
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Parent then
                local cubeCenter = p.Character.HumanoidRootPart.Position
                if rayToCubeIntersect(ray.Origin, ray.Direction, cubeCenter, hitboxSize) then
                    local distance = (ray.Origin - cubeCenter).Magnitude
                    if distance < bestDistance then bestDistance = distance; bestPlayer = p end
                end end end
        return bestPlayer
    end)
