        pcall(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            local AD = require(ReplicatedStorage:WaitForChild("Datas"):WaitForChild("Animals"))
            for idx, d in pairs(AD) do
