local function isPlotUnlocked(plotName, skipChan) LPH_ATTRIBUTES(ERROR_HANDLING(false))
    local ok, res, why = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if (not skipChan) and _G.JAF_NoSynchronizer ~= true and _G.JAF_LockChannelCheck ~= false then
            local okC, chLocked = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
                local Sync = _G.JAF_GetSynchronizer(); if not Sync then return false end
                local ch = Sync:Get(plotName)
                if not ch then return false end
                local now = Workspace:GetServerTimeNow()
                local function _lk(b) LPH_ATTRIBUTES(ERROR_HANDLING(false))
return b ~= nil and (type(b) ~= "number" or b > now) end
                return _lk(ch:Get("BlockEndTimeFirstFloor")) or _lk(ch:Get("BlockEndTimeSecondFloor"))
            end)
            if okC and chLocked then return false, "chan" end
        end
        local plots = Workspace:FindFirstChild("Plots"); if not plots then return false, "noPlots" end
        local plot  = plots:FindFirstChild(plotName);   if not plot  then return false, "noPlot" end
        local laser = plot:FindFirstChild("LaserHitbox")
        laser = laser and (laser:FindFirstChild("Main") or laser:FindFirstChildWhichIsA("BasePart"))
        if not laser then return false, "noLaser" end
        if laser.CanCollide then return false, "laserCC" end
        local uf = plot:FindFirstChild("Unlock")
        if uf then
            for _, d in ipairs(uf:GetDescendants()) do if d:IsA("ProximityPrompt") and d.Enabled then return false, "prompt" end end
        end
        if _G.JAF_LockGuiCheck ~= false then
            local pur = plot:FindFirstChild("Purchases")
            if pur then
                for _, d in ipairs(pur:GetDescendants()) do
                    if d:IsA("TextLabel") and d.Name == "Locked" and d.Visible then return false, "gui" end
                end end end
        return true
    end)
    if not ok then return false, "err" end
    return res == true, why
end
_G.JAF_BrainrotApproachSpeed = function() LPH_ATTRIBUTES(PRESET(FAST), ERROR_HANDLING(false))
