                local _sdx, _sdz, _ddx, _ddz = fx - cx, fz - cz, dxp - cx, dzp - cz
                local _sIn, _dIn
                if w.wheel or _G.JAF_SkipCoreRect == false or not (w.hx and w.hz) then
