                    if _parts then
                        local _bandTop = cruiseY + (tonumber(_G.JAF_PassUnderHead) or 6)
                        local _lowY = math.min(cruiseY, (fromPos and fromPos.Y) or cruiseY, (exactPos and exactPos.Y) or cruiseY)
                        local _bandBot, _band = _lowY - (tonumber(_G.JAF_PassOverFeet) or 3.0), {}
