        local baseCell, uwalls = math.max(tonumber(_G.JAF_GridCell) or 6, 1), {}
        local _aisleX, _dstF, _dstOpenFace, _stF, _stFace, _stWin, _dstWin = tonumber(_G.JAF_AisleX) or -410
        do
            local T, MU = math.max(tonumber(_G.JAF_BaseWallT) or (1.5 * baseCell), 1.5 * baseCell), tonumber(_G.JAF_DstExteriorBerth) or M
            local function _openFace(f, px, pz) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                local dn, dp, zn, zp = px - f.minX, f.maxX - px, pz - f.minZ, f.maxZ - pz
                local m = math.min(dn, dp, zn, zp)
