                    uwalls[#uwalls + 1] = _xf and { x0 = b0, z0 = alo, x1 = b1, z1 = ahi, jamb = JT } or { x0 = alo, z0 = b0, x1 = ahi, z1 = b1, jamb = JT }
                end
