            end
            local function _laserDoorZ(plotName) LPH_ATTRIBUTES(ERROR_HANDLING(false))
                local pf = Workspace:FindFirstChild("Plots")
                local lh = pf and plotName and pf:FindFirstChild(plotName)
                lh = lh and lh:FindFirstChild("LaserHitbox")
                local m = lh and (lh:FindFirstChild("Main") or lh:FindFirstChildWhichIsA("BasePart"))
                return m and m.Position.Z or nil
            end
            local startF, dstF
            for _, f in ipairs(_G.JAF_BaseFootprints or {}) do
                if f.minX and not startF and _inM(f, fx, fz, 0) then startF = f end
                if f.minX and not dstF and f.plot == _dsN then dstF = f end
            end
            if startF then
                local _sf = ((startF.minX + startF.maxX) * 0.5 <= _aisleX) and "+X" or "-X"
