            end
            if dstF and dstF ~= startF then
                local _front = ((dstF.minX + dstF.maxX) * 0.5 <= _aisleX) and "+X" or "-X"
                local _back  = (_front == "+X") and "-X" or "+X"
                local _band  = tonumber(_G.JAF_SideFlushBand) or 8
