                elseif _of == _back then _of = _front
                elseif _of == "-Z" or _of == "+Z" then
                    local _flush = (dzp - dstF.minZ <= _band) and "-Z" or ((dstF.maxZ - dzp <= _band) and "+Z" or nil)
                    if _flush ~= _of then _of = _front end
                end
                local _wc
                if _of == "-X" or _of == "+X" then _wc = _laserDoorZ(dstF.plot) else _wc = dxp end
                _dstWin = _addU(dstF, _of, _wc)
