            end end
        local function _clearW(ax, az, bx, bz) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            for _, b in ipairs(boxes) do if _segBox(ax, az, bx, bz, b) then return false end end
            for _, b in ipairs(uwalls) do if _segBox(ax, az, bx, bz, b) then return false end end
            return true
        end
        local MB = _G.JAF_MapBounds
        local haveMB = MB and MB.minX and MB.maxX and MB.minZ and MB.maxZ and MB.maxX > MB.minX and MB.maxZ > MB.minZ
        local function _inB(x, z) LPH_ATTRIBUTES(ERROR_HANDLING(false))
return (not haveMB) or (x >= MB.minX and x <= MB.maxX and z >= MB.minZ and z <= MB.maxZ) end
        local function _shortcut(route, clearFn) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            local pts = { Vector3.new(fx, cruiseY, fz) }
            for _, v in ipairs(route) do pts[#pts + 1] = v end
            for _pass = 1, 3 do
                local removed, i = false, 2
                while i <= #pts - 1 do
                    local a, c = pts[i - 1], pts[i + 1]
                    if clearFn(a.X, a.Z, c.X, c.Z) and _inB(c.X, c.Z) then table.remove(pts, i); removed = true else i = i + 1 end
                end
                if not removed then break end
            end
