            ranked[#ranked + 1] = { e = a, s = _G.JAF_PrioScore(a), i = #ranked }
        end end
    table.sort(ranked, function(x, y) LPH_ATTRIBUTES(ERROR_HANDLING(false))
if x.s ~= y.s then return x.s < y.s end return x.i < y.i end)
    for _, r in ipairs(ranked) do
        if r.s >= 999999 then break end
        seen[r.e.uid] = true; table.insert(out, r.e)
        if #out >= 10 then break end
    end
    if #out < 10 then
        for _, a in ipairs(cache) do
            if a and a.owner ~= LocalPlayer.Name and not seen[a.uid] then
                seen[a.uid] = true; table.insert(out, a); if #out >= 10 then break end
            end end end
    _top10Cache, _top10At = out, tick()
