            local bg = JUI.new("Frame", bb, "Size", UDim2.new(1,0,1,0), "BackgroundColor3", Color3.fromRGB(18,18,22), "BackgroundTransparency", 0.15, "BorderSizePixel", 0)
            Instance.new("UICorner", bg).CornerRadius = UDim.new(1,0)
