    local function resolvePlotOwner(plot) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        local c = ownerCache[plot.Name]
        if c and (tick() - c.t) < 3 then return c.plr or nil end
        local found = nil
        local sign = plot:FindFirstChild("PlotSign")
        if sign then
            local sg = sign:FindFirstChildWhichIsA("SurfaceGui", true)
            local lbl = sg and sg:FindFirstChildWhichIsA("TextLabel", true)
            if lbl then
                local text = (lbl.Text or ""):lower()
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LocalPlayer then
                        local dn = (p.DisplayName or ""):lower()
                        local un = (p.Name or ""):lower()
                        if (dn ~= "" and text:find(dn,1,true)) or (un ~= "" and text:find(un,1,true)) then found = p; break end
                    end end end end
        if not found and _G.JAF_NoSynchronizer ~= true then
            local Sync = _G.JAF_GetSynchronizer()
            if Sync then
                local okCh, ch = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return Sync:Get(plot.Name) end)
                if okCh and ch then
                    local okO, owner = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return ch:Get("Owner") end)
                    if okO and owner then found = _G.JAF_OwnerPlayer(owner) end
                end end end
        ownerCache[plot.Name] = { plr = found or false, t = tick() }
        return found
    end
    local function nearestBaseOwner(pos) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local plots = Workspace:FindFirstChild("Plots")
        if not plots then return nil end
        local bestName, bestD = nil, math.huge
        local fps = _G.JAF_BaseFootprints
        if fps and #fps > 0 then
            for _, f in ipairs(fps) do
                if f.minX then
                    local cx, cz = (f.minX + f.maxX)/2, (f.minZ + f.maxZ)/2
                    local dx, dz = pos.X - cx, pos.Z - cz
                    local d = dx*dx + dz*dz
                    if d < bestD then bestD = d; bestName = f.plot end
                end end end
        if not bestName then return nil end
        local plotInst = plots:FindFirstChild(bestName)
        if not plotInst then return nil end
        return resolvePlotOwner(plotInst)
    end
    Players.PlayerRemoving:Connect(function(p) LPH_ATTRIBUTES(ERROR_HANDLING(false))
removeEsp(p.UserId) end)
