        local oOn = Config.BaseOwnerESP == true
        if not sOn and not oOn then
            if next(state) then clearAll() end
            task.wait(0.5)
        else
            local ownerPlr = nil
            if oOn then
                local mc = LocalPlayer.Character
                local myHrp = mc and mc:FindFirstChild("HumanoidRootPart")
                if myHrp then ownerPlr = nearestBaseOwner(myHrp.Position) end
            end
            local desired = {}
