                    elseif oOn and ownerPlr and p == ownerPlr then
                        desired[p.UserId] = { p = p, kind = "owner", col = OWNER_COL, text = "BASE OWNER" }
                    end end end
            for uid in pairs(state) do if not desired[uid] then removeEsp(uid) end end
            for _, d in pairs(desired) do ensureEsp(d.p, d.kind, d.col, d.text) end
            task.wait(0.4)
        end end end)
