    if Config.TrapESP == nil then Config.TrapESP = true end
    local HESP_KINDS = {
        turret = { color = Color3.fromRGB(255, 40, 40),   text = "⚠ TURRET ⚠",        cfg = "TurretESP" },
        trap   = { color = Color3.fromRGB(255, 150, 20),  text = "⚠ TRAP ⚠",          cfg = "TrapESP"   },
