    }
    local hazardESPData = {}
    local sfind = string.find
    local TRAP_PATS = { "trap", "mine", "hive" }
    local hazardKind; hazardKind = (function(name) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local ln = name:lower()
        if sfind(ln, "sentrybullet", 1, true) then return nil end
        if sfind(ln, "tripmine", 1, true) then return "mine" end
        if sfind(ln, "sentry", 1, true) then return "turret" end
        for _, p in ipairs(TRAP_PATS) do if sfind(ln, p, 1, true) then return "trap" end end
        return nil
    end)
    local createHazardESP; createHazardESP = (function(target, kind) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
