        end
        local hl
        if target:IsA("Model") then
            hl = Instance.new("Highlight")
            _P(hl, "Name", "JAF_HazardESP_HL", "Adornee", target, "FillColor", spec.color, "FillTransparency", 0.25, "OutlineColor", Color3.fromRGB(255, 255, 255), "OutlineTransparency", 0)
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.Parent = target
        else
            hl = Instance.new("SelectionBox")
            _P(hl, "Name", "JAF_HazardESP_HL", "Adornee", target, "Color3", spec.color, "LineThickness", 0.12, "SurfaceColor3", spec.color, "SurfaceTransparency", 0.6, "Parent", target)
        end
        local bbAd = target:IsA("BasePart") and target or target:FindFirstChildWhichIsA("BasePart", true) or target
        local bb = Instance.new("BillboardGui")
        bb.Name = "JAF_HazardESP_Label"
        _P(bb, "Adornee", bbAd, "Size", UDim2.new(0, 200, 0, 44), "StudsOffset", Vector3.new(0, 6, 0), "AlwaysOnTop", true, "Parent", target)
        local lbl = JUI.new("TextLabel", bb, "Size", UDim2.new(1, 0, 1, 0), "BackgroundTransparency", 1, "Text", labelText, "TextColor3", spec.color, "TextStrokeColor3", Color3.fromRGB(0, 0, 0), "TextStrokeTransparency", 0, "Font", Enum.Font.GothamBold, "TextScaled", true)
        return { hl = hl, bb = bb, kind = kind }
