    local function destroyEntry(obj, data) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if data.hl and data.hl.Parent then data.hl:Destroy() end
        if data.bb and data.bb.Parent then data.bb:Destroy() end
        hazardESPData[obj] = nil
    end
    local refreshHazardESP; refreshHazardESP = (function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local kindOn = { turret = Config.TurretESP ~= false, trap   = Config.TrapESP ~= false, mine   = Config.TrapESP ~= false, }
        local current = {}
        if kindOn.turret or kindOn.trap or kindOn.mine then
            local _hz = workspace:GetDescendants()
            local _isaCN = _G.JAF_IsACN
            local _cap = _G.JAF_HazardBatch or 400
            local _budgetMs = (_G.JAF_XrayBudgetMs or 4) / 1000
            local _hn, _ht0 = 0, os.clock()
            for _hi = 1, #_hz do
                local inst = _hz[_hi]
                _hn = _hn + 1
                if _hn >= _cap or (os.clock() - _ht0) >= _budgetMs then RunService.Heartbeat:Wait() _hn = 0 _ht0 = os.clock() end
                local _cn = inst.ClassName
                if _cn == "Model" or _isaCN(_cn, inst, "BasePart") then
                    local kind = hazardKind(inst.Name)
                    if kind and kindOn[kind] then
                        local par, skip = inst, false
                        if inst:FindFirstChildWhichIsA("Humanoid", true) then skip = true end
                        while not skip and par and par ~= workspace do
                            if Players:GetPlayerFromCharacter(par)
                            or (par.ClassName == "Model" and par:FindFirstChildOfClass("Humanoid")) then
                                skip = true; break
                            end
                            if par ~= inst and hazardKind(par.Name) then skip = true; break end
                            par = par.Parent
                        end
                        if not skip then
                            current[inst] = true
                            local data = hazardESPData[inst]
                            if data and data.kind ~= kind then destroyEntry(inst, data); data = nil end
                            if not data then hazardESPData[inst] = createHazardESP(inst, kind) end
                        end end end end end
        for obj, data in pairs(hazardESPData) do if not current[obj] or not obj.Parent then destroyEntry(obj, data) end end
    end)
    while true do task.wait(tonumber(_G.JAF_HazardESPEvery) or 1.5) pcall(refreshHazardESP) end
end)
