        local function refresh() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            local cur = get()
            local c2 = C()
            for _, b in ipairs(btns) do
                local on = (b.v == cur)
                b.btn.BackgroundColor3 = on and Theme.Accent1 or c2.SH
                b.btn.TextColor3       = on and _G.JAF_OnAccent() or c2.TP
            end end
        for i, o in ipairs(opts) do
            local b = JUI.new("TextButton", row, "Size", UDim2.new(0,52,0,24), "Position", UDim2.new(1, x0 + (i-1)*57, 0.5, -12), "Font", Enum.Font.GothamMedium, "TextSize", 9, "Text", o.t, "AutoButtonColor", false, "BorderSizePixel", 0)
            JUI.corner(b, 5)
            btns[#btns+1] = {btn=b, v=o.v}
            _G.JAF_OnTap(b, function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                if get() == o.v then return end
                set(o.v); SaveConfig(); refresh()
            end) end
        refresh()
        return row, refresh
    end
