        local vl = JUI.new("TextLabel", r, "Size", UDim2.new(0,38,0,18), "Position", UDim2.new(1,-42,0.5,-9), "BackgroundTransparency", 1, "Font", Enum.Font.GothamBold, "TextSize", 13, "TextColor3", Theme.TextPrimary, "TextXAlignment", Enum.TextXAlignment.Right)
        local bg2 = JUI.new("Frame", r, "Size", UDim2.new(0,80,0,4), "Position", UDim2.new(1,-128,0.5,-2), "BackgroundColor3", cs.SH, "BorderSizePixel", 0)
        JUI.round(bg2)
