        JUI.round(fi2)
        local kn2 = JUI.new("Frame", bg2, "Size", UDim2.new(0,10,0,10), "BackgroundColor3", Theme.TextPrimary, "AnchorPoint", Vector2.new(0.5,0.5), "Position", UDim2.new(0,0,0.5,0), "BorderSizePixel", 0)
        JUI.round(kn2)
        local function upd(v, save) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            v=math.floor(v/step+0.5)*step; v=math.clamp(v,lo,hi)
