        if string.find(hay, needle, 1, true) then return true end
        local hi, ni = 1, 1
        local hlen, nlen = #hay, #needle
        while hi <= hlen and ni <= nlen do if string.byte(hay, hi) == string.byte(needle, ni) then ni = ni + 1 end hi = hi + 1 end
