    function _G.JAF_DestroyTurretIfThreat() LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if not (autoTurretOn and SAB_LIVE()) then return false end
        if _G.JAF_TurretYieldToBuyKick ~= false then if _G.JAF_AutoBuyActive and _G.JAF_AutoBuyActive() then return false end end
        local _, hrp = adt_getChar()
        if not hrp then return false end
        local s = adt_getClosestSentry(true)
        if not s then return false end
        local root = s:IsA("BasePart") and s or s:FindFirstChildWhichIsA("BasePart", true)
        if not root then return false end
        if (hrp.Position - root.Position).Magnitude > (tonumber(_G.JAF_TurretHitRange) or 45) then return false end
        if not adt_getWeapon() then return false end
        adt_equipBat()
        adt_destroyCycle(s)
        return true
    end
    function _G.JAF_TurretThreatNearby() LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if not (autoTurretOn and SAB_LIVE()) then return false end
        local _, hrp = adt_getChar()
        if not hrp then return false end
        local s = adt_getClosestSentry(true)
        if not s then return false end
        local root = s:IsA("BasePart") and s or s:FindFirstChildWhichIsA("BasePart", true)
        if not root then return false end
        return (hrp.Position - root.Position).Magnitude <= (tonumber(_G.JAF_TurretHitRange) or 45)
    end
    local adt_boot = tick()
    local adt_sweepIdx, adt_lastSweep = 0, 0
    local adt_lastScan, adt_hadTarget = 0, false
    local adt_sweeping = false
    local adt_known = 0
    local adt_whyLog = {}
    local function _why(s) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if _G.JAF_TurretWhy ~= s then
            _G.JAF_TurretWhy = s
            local L = adt_whyLog
            L[#L + 1] = string.format("%.1f %s", tick() - adt_boot, s)
            if #L > 24 then table.remove(L, 1) end
            _G.JAF_TurretWhyLog = table.concat(L, " | ")
        end end
    task.spawn(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
        local adt_lastTick, adt_dt = tick(), 0
        local function _gate(name) LPH_ATTRIBUTES(ERROR_HANDLING(false))
