            if _G.JAF_TurretObserve ~= false then
                local n, kids = 0, workspace:GetChildren()
                for i = 1, #kids do
                    local inst = kids[i]
                    local nm = inst.Name
                    if string.find(nm, "Sentry", 1, true) and nm ~= "SentryBullet"
                      and (inst.ClassName == "Model" or inst:IsA("BasePart"))
                      and not adt_isPlayerRig(inst) then
