task.spawn(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
    local OWN_CLONE_NAME = tostring(LocalPlayer.UserId) .. "_Clone"
    local isOtherClone; isOtherClone = function(inst) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not inst:IsA("Model") then return false end
