        if not (type(n) == "string" and string.find(n, "_Clone", 1, true)) then return false end
        return n ~= OWN_CLONE_NAME
    end
    local disableCollide; disableCollide = function(root) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not root or not root.Parent then return end
        for _, d in ipairs(root:GetDescendants()) do
            if d:IsA("BasePart") and d.CanCollide then pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
d.CanCollide = false end) end
        end end
    while true do
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then disableCollide(p.Character) RunService.Heartbeat:Wait() end
        end
        for _, child in ipairs(Workspace:GetChildren()) do
            if isOtherClone(child) then disableCollide(child) RunService.Heartbeat:Wait() end
        end
        task.wait(_G.JAF_NoclipInterval or 0.4)
    end end)
do
    local function silenceFriendPanel() LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if _G.JAF_SilenceFriendPanel == false or typeof(getconnections) ~= "function" then return 0 end
        local CS = game:GetService("CollectionService")
        local killed = 0
        for _, sig in ipairs({ CS:GetInstanceAddedSignal("PlotFriendPanel"), CS:GetInstanceRemovedSignal("PlotFriendPanel") }) do
            local ok, conns = pcall(getconnections, sig)
            if ok and conns then
                for _, c in ipairs(conns) do
                    local on = true
                    pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
on = c.Enabled end)
                    if on ~= false then
                        if not pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
c:Disable() end) then pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
c:Disconnect() end) end
