        end end
    local function _coreGui() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local ok, cg = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return (gethui and gethui()) or game:GetService("CoreGui") end)
